local Engraver = {}
local PRODUCTS = {
    nameplate = { name = "Napisna plošča", metalCost = 2, time = 3, cost = 30, description = "Kovinska napisna plošča." },
    memorial_plate = { name = "Spominska plošča", metalCost = 3, time = 7, cost = 100, prestige = 5, description = "Spominska plošča za dogodke." },
    etching_plate = { name = "Bakrenična plošča", copperCost = 2, time = 5, cost = 60, knowledge = 5, description = "Za tiskanje grafik." },
    engraved_goblet = { name = "Vgraviran kelih", metalCost = 3, time = 10, cost = 150, prestige = 8, happiness = 3, description = "Vgraviran kelih." },
    engraved_armor = { name = "Vgraviran oklep", metalCost = 5, time = 14, cost = 300, prestige = 12, militaryBonus = 5, description = "Oklep z gravuro." },
    royal_engraving = { name = "Kraljevska gravura", goldCost = 2, jewelCost = 1, time = 20, cost = 600, prestige = 25, happiness = 8, description = "Zlata plošča z drago gravuro." },
}
local BUILDINGS = {
    workshop = { name = "Graverska delavnica", cost = { gold = 300, wood = 100, iron = 50 }, upkeep = 8, qualityBonus = 5 },
    etching_studio = { name = "Jetska delavnica", cost = { gold = 1000, wood = 200, stone = 200, copper = 30 }, upkeep = 25, qualityBonus = 20 },
    acid_room = { name = "Kislinska soba", cost = { gold = 800, wood = 200, stone = 300 }, upkeep = 20, qualityBonus = 15 },
    royal_engraving = { name = "Kraljevski graver", cost = { gold = 4000, wood = 400, stone = 800, gold = 50 }, upkeep = 80, qualityBonus = 40, prestigeBonus = 20 },
}
Engraver.metalStock = 10; Engraver.copperStock = 5; Engraver.goldStock = 3; Engraver.jewelStock = 2
Engraver.productStock = {}; Engraver.buildings = {}; Engraver.engraver = nil; Engraver.activeMaking = {}; Engraver.totalProducts = 0; Engraver.dayTimer = 0
function Engraver.init() Engraver.metalStock=10; Engraver.copperStock=5; Engraver.goldStock=3; Engraver.jewelStock=2; Engraver.productStock={}; Engraver.buildings={}; Engraver.engraver=nil; Engraver.activeMaking={}; Engraver.totalProducts=0; Engraver.dayTimer=0; print("[Engraver] Royal Engraver & Etcher System initialized (6 products, 4 buildings)") end
function Engraver.hireEngraver(n,s) s=s or math.random(40,85); local c=350+s*7; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Engraver.engraver={name=n or ("Graver "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Graver najet: %s (spretnost: %d)",Engraver.engraver.name,s),"success") end; return true end
function Engraver.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Engraver.build(id) local ok,e=Engraver.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Engraver.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Engraver.getQualityBonus() local b=0; for _,bd in ipairs(Engraver.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Engraver.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.metalCost and Engraver.metalStock<(d.metalCost or 0) then return false,"Premalo kovine" end; if d.copperCost and Engraver.copperStock<(d.copperCost or 0) then return false,"Premalo bakra" end; if d.goldCost and Engraver.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and Engraver.jewelStock<(d.jewelCost or 0) then return false,"Premalo dragih kamnov" end; if #Engraver.buildings==0 then return false,"Potrebna delavnica" end; if not Engraver.engraver then return false,"Potreben graver" end; return true end
function Engraver.make(pt) local ok,e=Engraver.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.metalCost then Engraver.metalStock=Engraver.metalStock-d.metalCost end; if d.copperCost then Engraver.copperStock=Engraver.copperStock-d.copperCost end; if d.goldCost then Engraver.goldStock=Engraver.goldStock-d.goldCost end; if d.jewelCost then Engraver.jewelStock=Engraver.jewelStock-d.jewelCost end; local t=d.time; if Engraver.engraver then t=math.max(1,t-math.floor(Engraver.engraver.skill/10)) end; table.insert(Engraver.activeMaking,{id="engrave_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,prestige=d.prestige or 0,happiness=d.happiness or 0,knowledge=d.knowledge or 0,militaryBonus=d.militaryBonus or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Graviranje: %s (%d dni)",d.name,t),"info") end; return true end
function Engraver.completeMaking(m) local q=1.0+(Engraver.getQualityBonus()/100); if Engraver.engraver then q=q+(Engraver.engraver.skill/200) end; q=math.min(2.5,q); Engraver.productStock[m.productType]=(Engraver.productStock[m.productType] or 0)+1; Engraver.totalProducts=Engraver.totalProducts+1; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if m.knowledge>0 and _G.Culture then pcall(function() _G.Culture.knowledgePoints=(_G.Culture.knowledgePoints or 0)+m.knowledge end) end; if Engraver.engraver then Engraver.engraver.itemsMade=Engraver.engraver.itemsMade+1; if math.random()<0.15 then Engraver.engraver.skill=math.min(100,Engraver.engraver.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gravura dokončana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function Engraver.update(dt) if not _G.state then return end; Engraver.dayTimer=Engraver.dayTimer+dt; if Engraver.dayTimer>=30 then Engraver.dayTimer=0; for i=#Engraver.activeMaking,1,-1 do local m=Engraver.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Engraver.completeMaking(m); table.remove(Engraver.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Engraver.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Engraver.engraver then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Engraver.getStats() return {metalStock=Engraver.metalStock,copperStock=Engraver.copperStock,goldStock=Engraver.goldStock,jewelStock=Engraver.jewelStock,productStock=Engraver.productStock,numBuildings=#Engraver.buildings,hasEngraver=Engraver.engraver~=nil,engraverName=Engraver.engraver and Engraver.engraver.name or "—",engraverSkill=Engraver.engraver and Engraver.engraver.skill or 0,activeMaking=#Engraver.activeMaking,totalProducts=Engraver.totalProducts} end
return Engraver
